public void connect(int p, int q) {          // Quick Find
    int pid = id[p], qid = id[q];
    for (int i = 0; i < id.length; i++)
        if (id[i] == pid) id[i] = qid;
}
public boolean isConnected(int p, int q) { return id[p] == id[q]; }

public int find(int p) {
    while (parent[p] >= 0) p = parent[p];
    return p;
}
public void connect(int p, int q) {
    int a = find(p), b = find(q);
    if (a == b) return;
    if (-parent[a] <= -parent[b]) {          // a's tree is smaller or tied
        parent[b] += parent[a];              // sizes are negative: add them
        parent[a] = b;
    } else {
        parent[a] += parent[b];
        parent[b] = a;
    }
}

public int find(int p) {                 // WQU with path compression
    int r = p;
    while (parent[r] >= 0) r = parent[r];          // find the root
    while (parent[p] >= 0) {                        // re-point the path
        int next = parent[p];
        parent[p] = r;
        p = next;
    }
    return r;
}

