public void compress() {
    for (int i = 0; i < parent.length; i++) {
        if (parent[i] >= 0) parent[i] = find(i);   // sizes at roots unchanged
    }
}

class UF<T> {
    private Map<T, T> parent = new HashMap<>();
    private Map<T, Integer> size = new HashMap<>();
    private T find(T x) {
        if (!parent.containsKey(x)) { parent.put(x, x); size.put(x, 1); }
        while (!parent.get(x).equals(x)) x = parent.get(x);
        return x;
    }
    public void connect(T a, T b) {
        T ra = find(a), rb = find(b);
        if (ra.equals(rb)) return;
        if (size.get(ra) <= size.get(rb)) { parent.put(ra, rb); size.put(rb, size.get(ra) + size.get(rb)); }
        else { parent.put(rb, ra); size.put(ra, size.get(ra) + size.get(rb)); }
    }
    public boolean isConnected(T a, T b) { return find(a).equals(find(b)); }
}
